import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.BrSBneze.js";const p=JSON.parse('{"title":"Contribution requirements and credit","description":"Required files, validation evidence, and contributor credit for the HiveBoard asset calls.","frontmatter":{"description":"Required files, validation evidence, and contributor credit for the HiveBoard asset calls."},"headers":[],"relativePath":"contribute/requirements.md","filePath":"contribute/requirements.md","lastUpdated":1788882780000}'),n={name:"contribute/requirements.md"};function o(s,e,d,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="contribution-requirements-and-credit" tabindex="-1">Contribution requirements and credit <a class="header-anchor" href="#contribution-requirements-and-credit" aria-label="Permalink to &quot;Contribution requirements and credit&quot;">​</a></h1><p>These requirements apply to the <a href="/hiveboard-docs/contribute/adl">ADL</a> and <a href="/hiveboard-docs/contribute/bimanual">bimanual manipulation</a> calls. Discuss the proposal with the authors before starting detailed design. Use the <a href="/hiveboard-docs/guides/new-attachment">attachment guide</a> for technical integration.</p><h2 id="required-files-and-evidence" tabindex="-1">Required files and evidence <a class="header-anchor" href="#required-files-and-evidence" aria-label="Permalink to &quot;Required files and evidence&quot;">​</a></h2><p>A complete asset contribution must let another laboratory fabricate, assemble, simulate, and operate the mechanism.</p><table tabindex="0"><thead><tr><th>Component</th><th>Required material</th></tr></thead><tbody><tr><td>Editable design</td><td>Native CAD source and a neutral exchange format such as STEP; dimensions and mounting geometry</td></tr><tr><td>Printable parts</td><td>STL files for every printed component, with units, quantities, orientation, and printing settings</td></tr><tr><td>Assembly</td><td>Bill of materials, specifications for non-printed parts, illustrated assembly instructions, and an assembled-prototype photograph</td></tr><tr><td>Simulation</td><td>Articulated URDF and/or USD model in the format agreed with the authors; all referenced visual and collision meshes; joint axes, limits, initial values, and documented physical parameters</td></tr><tr><td>Simulation check</td><td>Loading instructions, software versions, and a runnable script or reproducible procedure that exercises the moving parts</td></tr><tr><td>Task definition</td><td>Initial state, action sequence, success criterion, timeout, intermediate stages where needed, failure conditions, and reset procedure</td></tr><tr><td>Physical validation</td><td>External-camera video showing mounting, full mechanism operation, successful task execution, and reset; both hands visible for a bimanual task</td></tr><tr><td>Trial example</td><td>At least one completed example trial record, identifying the mechanism version, performer or platform, and any known limitations</td></tr><tr><td>Attribution and provenance</td><td>Contributor names and roles, sources of reused material, and the existing licenses or permissions for those materials</td></tr></tbody></table><p>Identify measured physical parameters separately from nominal simulation values. A render alone does not demonstrate a functional asset. Label human demonstrations and robot trials accurately; discuss the available validation platform with the authors during the proposal stage.</p><h2 id="submission-and-review" tabindex="-1">Submission and review <a class="header-anchor" href="#submission-and-review" aria-label="Permalink to &quot;Submission and review&quot;">​</a></h2><ol><li><strong>Propose the task.</strong> Send the idea and sketch to <a href="mailto:ricardo.godoy@usp.br" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a>. The authors check scope, overlap, feasibility, and the intended contribution.</li><li><strong>Agree on the deliverables.</strong> Confirm mounting, simulation format, validation evidence, and applicable contribution licenses before preparing the final package.</li><li><strong>Build and validate.</strong> Complete the files above and document any unresolved limitations.</li><li><strong>Submit for review.</strong> Send a repository or file-package link to the authors. They will coordinate the pull request to the appropriate HiveBoard repository. Include a short file index and the contributor roles.</li><li><strong>Address review comments.</strong> Acceptance depends on function, reproducibility, task relevance, and file completeness. The maintainers coordinate integration into a versioned extension.</li></ol><p>The example record validates the proposed task description; it does not constitute a complete benchmark evaluation. Evaluations of the current benchmark still require <strong>all 13 conditions and five trials per condition</strong>.</p><h2 id="authorship-and-acknowledgments" tabindex="-1">Authorship and acknowledgments <a class="header-anchor" href="#authorship-and-acknowledgments" aria-label="Permalink to &quot;Authorship and acknowledgments&quot;">​</a></h2><p>Anyone who contributes <strong>at least one accepted, functional asset with all required files and validation evidence</strong> may be eligible for authorship on future HiveBoard papers that use and report that contribution.</p><p>Authorship is assessed for each paper. Eligible contributors should also participate in drafting or substantive revision of the paper, approve its final version, and take responsibility for their contribution. Asset acceptance does not guarantee authorship on every future HiveBoard paper or establish author order. The authors will discuss the expected role when planning the relevant paper.</p><p>Smaller contributions, such as design suggestions, documentation corrections, or limited testing, may be credited in the acknowledgments with the contributor&#39;s consent. These contributions are also welcome. Keep a record of each person&#39;s work so credit reflects the contribution made.</p>',13)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
